                "es": "Introduce potencia y tiempo: 2 kW durante tres horas consumen 6 kWh. Para calcular el coste, añade tu precio por kWh y etiqueta de moneda. Sin precio muestra solo energía; no consulta tarifas ni tipos de cambio.",
                "fr": "Saisissez puissance et durée : 2 kW pendant trois heures consomment 6 kWh. Pour le coût, ajoutez votre prix par kWh et le libellé de monnaie. Sans prix, seule l’énergie apparaît ; aucun tarif ni taux de change n’est récupéré.",
