                "en": "Search by category, function, unit name, symbol or familiar synonym. Searching lux can find both the illuminance converter and lighting calculator. Open a result to reach its function.",
                "hu": "Keress kategóriával, funkcióval, egységnévvel, jellel vagy rokon kifejezéssel. A lux a megvilágítás átváltóját és a világítástechnikai kalkulátort is megtalálhatja. A találat a megfelelő funkciót nyitja meg.",
                "de": "Suche nach Kategorie, Funktion, Einheit, Symbol oder geläufigem Synonym. Lux findet etwa den Beleuchtungsstärke-Umrechner und Lichtrechner. Ein Treffer öffnet die passende Funktion.",
