                "pt-BR": "Informe dimensões de trechos ou volume conhecido. Veja volume de concreto com sobra. Informe rendimento por saco para estimar sacos inteiros. Não escolhe mistura nem calcula resistência estrutural.",
                "pl": "Podaj wymiary odcinków lub znaną objętość. Wynik to objętość betonu z zapasem. Wydajność worka daje całe worki. Nie dobiera mieszanki ani nie oblicza wytrzymałości konstrukcji.",
                "it": "Inserisci dimensioni di sezioni o volume noto. Vedi volume di calcestruzzo con margine. Indica resa per sacco per stimare sacchi interi. Non sceglie miscela né calcola resistenza strutturale."
