                "hu": "A Névjegy logójára hétszer koppintva mintás tapétatekercs gördül végtelenül. Az offline meglepetés bezárható, méretet, sablont vagy beállítást nem módosít. Csökkentett mozgásnál is felismerhető marad a minta.",
                "de": "Tippe siebenmal auf das Über-die-App-Logo für eine endlos abrollende Mustertapete. Schließe die Offline-Überraschung; Maße, Vorlagen und Einstellungen bleiben gleich. Bei reduzierter Bewegung bleibt das Muster verständlich.",
                "es": "Toca siete veces el logo de Acerca de para un rollo estampado infinito. Cierra la sorpresa sin conexión; no cambia medidas, preajustes ni ajustes. Con movimiento reducido el patrón sigue reconocible.",
                "fr": "Touchez sept fois le logo dans À propos pour un rouleau à motifs infini. Fermez la surprise hors ligne ; mesures, préréglages et réglages ne changent pas. Le motif reste lisible avec mouvement réduit.",
                "pt-BR": "Toque sete vezes no logo em Sobre para um rolo estampado infinito. Feche a surpresa offline; não muda medidas, predefinições ou ajustes. Com movimento reduzido o padrão continua reconhecível.",
                "pl": "Dotknij logo w informacjach siedem razy dla nieskończonej rolki wzorzystej tapety. Zamknij niespodziankę offline; nie zmienia wymiarów, szablonów ani ustawień. Przy ograniczonym ruchu wzór pozostaje czytelny.",
                "it": "Tocca sette volte il logo in Informazioni per un rotolo decorato infinito. Chiudi la sorpresa offline; non cambia misure, preimpostazioni o impostazioni. Con movimento ridotto il motivo resta riconoscibile."
