                "es": "Toca siete veces el logo de Acerca de: imagen de muestra se comprime cómicamente hasta un píxel grande. La sorpresa sin conexión no usa fotos personales ni cambia archivos o ajustes reales.",
                "fr": "Touchez sept fois le logo dans À propos : une image intégrée se compresse comiquement jusqu’à un gros pixel. La surprise hors ligne n’utilise aucune image personnelle ni ne change les résultats ou réglages.",
