            {
              "id": "tuner-metronome-settings",
              "title": {
                "en": "Language, settings and help",
                "hu": "Nyelv, beállítások és segítség",
                "de": "Sprache, Einstellungen und Hilfe",
                "es": "Idioma, ajustes y ayuda",
                "fr": "Langue, réglages et aide",
                "pt-BR": "Idioma, ajustes e ajuda",
                "pl": "Język, ustawienia i pomoc",
                "it": "Lingua, impostazioni e aiuto"
              },
              "text": {
                "en": "Choose one of eight app languages and adjust the available settings. About provides privacy information and a link to voluntary JN86 support. Support does not unlock paid functions. Availability is shown below.",
                "hu": "Nyolc alkalmazásnyelvből választhatsz, és módosíthatod az elérhető beállításokat. A Névjegyből adatvédelmi tájékoztatás és önkéntes JN86-támogatás érhető el. A támogatás nem old fel fizetős funkciót. Az elérhetőség alább látható.",
                "de": "Wähle eine von acht App-Sprachen und passe verfügbare Einstellungen an. Über die App bietet Datenschutzinformationen und freiwillige JN86-Unterstützung. Unterstützung schaltet keine Bezahlfunktionen frei. Die Verfügbarkeit steht unten.",
                "es": "Elige uno de ocho idiomas y cambia los ajustes disponibles. Acerca de ofrece información de privacidad y apoyo voluntario a JN86. Apoyar no desbloquea funciones de pago. La disponibilidad figura abajo.",
                "fr": "Choisissez l’une des huit langues et adaptez les réglages disponibles. À propos donne accès aux informations de confidentialité et au soutien volontaire à JN86. Le soutien ne débloque pas de fonctions payantes. La disponibilité figure ci-dessous.",
                "pt-BR": "Escolha um dos oito idiomas e ajuste as configurações disponíveis. Sobre oferece informações de privacidade e apoio voluntário ao JN86. Apoiar não libera funções pagas. A disponibilidade aparece abaixo.",
                "pl": "Wybierz jeden z ośmiu języków i zmień dostępne ustawienia. Informacje o aplikacji zawierają prywatność i dobrowolne wsparcie JN86. Wsparcie nie odblokowuje płatnych funkcji. Dostępność podano niżej.",
                "it": "Scegli una delle otto lingue e modifica le impostazioni disponibili. Informazioni offre privacy e sostegno volontario a JN86. Il sostegno non sblocca funzioni a pagamento. La disponibilità è indicata sotto."
              }
            },
            {
              "id": "tuner-metronome-ads",
              "title": {
                "en": "Ads and optional ad removal",
                "hu": "Reklámok és választható reklámmentesítés",
                "de": "Werbung und optionale Entfernung",
                "es": "Anuncios y eliminación opcional",
                "fr": "Publicités et suppression facultative",
                "pt-BR": "Anúncios e remoção opcional",
                "pl": "Reklamy i opcjonalne usunięcie",
                "it": "Pubblicità e rimozione facoltativa"
              },
              "text": {
                "en": "All described functions are planned to be free, with banner ads and optional one-time Google Play ad removal. No subscription is planned. The purchase screen shows the actual local price; purchase restoration uses Google Play.",
                "hu": "A bemutatott funkciók a terv szerint ingyenesek, bannerreklámmal és választható, egyszeri Google Play-reklámmentesítéssel. Előfizetés nincs a tervben. A vásárlási felület mutatja a tényleges helyi árat; a helyreállítás Google Playen történik.",
                "de": "Alle beschriebenen Funktionen sind kostenlos mit Bannerwerbung und optionaler einmaliger Werbeentfernung über Google Play vorgesehen. Ein Abo ist nicht geplant. Der Kaufdialog zeigt den lokalen Preis; Käufe werden über Google Play wiederhergestellt.",
                "es": "Todas las funciones descritas se prevén gratis con banners y eliminación opcional mediante un único pago en Google Play. No se prevé suscripción. La compra muestra el precio local real; la restauración usa Google Play.",
                "fr": "Toutes les fonctions décrites sont prévues gratuites avec bannières et suppression facultative par achat unique Google Play. Aucun abonnement n’est prévu. L’achat affiche le prix local réel ; la restauration passe par Google Play.",
                "pt-BR": "Todas as funções descritas são previstas grátis com banners e remoção opcional por compra única no Google Play. Não há assinatura prevista. A compra mostra o preço local real; a restauração usa o Google Play.",
                "pl": "Wszystkie opisane funkcje są planowane bezpłatnie z banerami i opcjonalnym jednorazowym usunięciem reklam przez Google Play. Nie przewidziano subskrypcji. Zakup pokazuje rzeczywistą cenę lokalną; przywracanie używa Google Play.",
                "it": "Tutte le funzioni descritte sono previste gratuite con banner e rimozione facoltativa tramite acquisto unico Google Play. Non è previsto un abbonamento. L’acquisto mostra il prezzo locale reale; il ripristino usa Google Play."
              }
            }
