                "en": "The main functions are designed to work on your device without a JN86 account. Ads, purchases and external links may need internet.",
                "hu": "Az alapfunkciók a készüléken, JN86-fiók nélkül használhatók a terv szerint. Reklámhoz, vásárláshoz és külső linkhez internet kellhet.",
