              "text": {
                "en": "Back up lottery/filter profiles, draw history, saved combinations and settings to your chosen file. Restore all or selected categories after checking a preview. Merging is default; replacing current data needs explicit confirmation. Resolve name conflicts by keeping both, the existing or restored version. Data recovery does not grant ad-free purchase access.",
                "hu": "Lottó/szűrőprofilt, húzáselőzményt, kombinációt és beállítást választott fájlba menthetsz. Teljes vagy kijelölt kategória előnézet után állítható helyre. Összevonás alap, csere külön megerősített. Névütközésnél mindkettő, meglévő vagy mentett megtartható. Adathelyreállítás nem ad vásárolt reklámmentességet.",
                "de": "Sichere Profile, Verlauf, Kombinationen, Einstellungen zur Datei. Stelle alles/gewählte Kategorien nach Vorschau her. Zusammenführen Standard, Ersatz bestätigt. Namenskonflikt: beide, bestehend oder gesichert. Datenrestore gibt keinen Kaufzugang.",
                "es": "Copia perfiles, historial, combinaciones, ajustes a archivo. Restaura todo/categorías tras vista previa. Fusionar defecto, reemplazo confirmado. Nombres: ambos, existente o guardado. Datos no conceden compra sin anuncios.",
                "fr": "Sauvegardez profils, historique, combinaisons, réglages au fichier. Restaurez tout/catégories après aperçu. Fusion par défaut, remplacement confirmé. Noms : les deux, existant ou sauvegardé. Données ne donnent pas achat sans pub.",
                "pt-BR": "Salve perfis, histórico, combinações, ajustes em arquivo. Restaure tudo/categorias após prévia. Mesclar padrão, substituir confirmado. Nomes: ambos, existente ou salvo. Dados não dão compra sem anúncios.",
                "pl": "Zapisz profile, historię, kombinacje, ustawienia do pliku. Przywróć wszystko/kategorie po podglądzie. Scalenie domyślnie, zastąpienie potwierdzone. Nazwy: oba, istniejące lub zapisane. Dane nie dają zakupu bez reklam.",
                "it": "Salva profili, cronologia, combinazioni, impostazioni al file. Ripristina tutto/categorie dopo anteprima. Unire base, sostituire confermato. Nomi: entrambi, esistente o salvato. Dati non danno acquisto senza pubblicità."
              }
