                "pl": "Wybierz odrzucaną długość kolejnych 1,8,27,64. 1–8–27 trójka; 1–27–64 nie kolejne.",
                "it": "Scegli lunghezza rifiutata di consecutivi 1,8,27,64. 1–8–27 tripla; 1–27–64 non consecutivi."
